+++ b/src/main/java/hotel/reservations/PriceCalculator.java
@@ -5,32 +5,38 @@ import java.math.BigDecimal;
 import java.math.RoundingMode;
 import java.time.LocalDate;
 import java.time.Month;
+import java.time.temporal.ChronoUnit;

 /**
  * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
- * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
+ * high-season nights; the rate plan then decides the subtotal and the discount. Money is rounded to cents
  * (half-even) at every step.
  */
 public final class PriceCalculator {

     static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
-    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");

-    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
-        int nights = 0;
-        BigDecimal subtotal = cents(BigDecimal.ZERO);
+    public Price calculate(Room room, NewReservation request) {
+        RatePlan ratePlan = request.ratePlan();
+        BigDecimal subtotal = ratePlan.subtotal(request, room);
+        BigDecimal discount = ratePlan.discount(request, subtotal);
+        return new Price(
+                nights(request.checkIn(), request.checkOut()), subtotal, discount, subtotal.subtract(discount));
+    }
+
+    static BigDecimal nightsTotal(Room room, LocalDate checkIn, LocalDate checkOut) {
+        BigDecimal total = cents(BigDecimal.ZERO);
         for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
-            subtotal = subtotal.add(nightPrice(room, night));
-            nights++;
+            total = total.add(nightPrice(room, night));
         }
-        BigDecimal discount = switch (ratePlan) {
-            case STANDARD -> cents(BigDecimal.ZERO);
-            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
-        };
-        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
+        return total;
+    }
+
+    static int nights(LocalDate checkIn, LocalDate checkOut) {
+        return (int) ChronoUnit.DAYS.between(checkIn, checkOut);
     }

-    BigDecimal nightPrice(Room room, LocalDate night) {
+    static BigDecimal nightPrice(Room room, LocalDate night) {
         BigDecimal nightlyRate = room.nightlyRate();
         if (isHighSeason(night)) {
             return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
@@ -47,6 +53,10 @@ public final class PriceCalculator {
                 || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
     }

+    static BigDecimal percentOf(BigDecimal amount, BigDecimal rate) {
+        return cents(amount.multiply(rate));
+    }
+
     static BigDecimal cents(BigDecimal value) {
         return value.setScale(2, RoundingMode.HALF_EVEN);
     }
diff --git a/src/main/java/hotel/reservations/RatePlan.java b/src/main/java/hotel/reservations/RatePlan.java
index 5c0e217..6ba1da5 100644
--- a/src/main/java/hotel/reservations/RatePlan.java
+++ b/src/main/java/hotel/reservations/RatePlan.java
@@ -1,8 +1,109 @@
 package hotel.reservations;

+import hotel.rooms.Room;
+import hotel.rooms.RoomType;
+import java.math.BigDecimal;
+import java.time.DayOfWeek;
+import java.util.Map;
+
+/** Each plan decides who can use it, the subtotal and discount of a stay, and what comes back when cancelling. */
 public enum RatePlan {
+
     /** Full price; the guest gets everything back when cancelling a confirmed reservation. */
     STANDARD,
+
     /** 15% off, but nothing comes back on cancellation. */
-    NON_REFUNDABLE
+    NON_REFUNDABLE {
+        @Override
+        BigDecimal discount(NewReservation request, BigDecimal subtotal) {
+            return PriceCalculator.percentOf(subtotal, new BigDecimal("0.15"));
+        }
+
+        @Override
+        BigDecimal refund(BigDecimal amountPaid) {
+            return PriceCalculator.cents(BigDecimal.ZERO);
+        }
+    },
+
+    /** The discount a company agreed with the inn; the guest must give the company's code. */
+    CORPORATE {
+        @Override
+        void checkEligibility(NewReservation request) {
+            if (request.companyCode() == null || !COMPANY_DISCOUNTS.containsKey(request.companyCode())) {
+                throw new HotelException(ErrorCode.INVALID_REQUEST, "a corporate reservation needs a valid company code");
+            }
+        }
+
+        @Override
+        BigDecimal discount(NewReservation request, BigDecimal subtotal) {
+            return PriceCalculator.percentOf(subtotal, COMPANY_DISCOUNTS.get(request.companyCode()));
+        }
+    },
+
+    /** A fixed price for two nights from Friday to Sunday, in any season. Half comes back on cancellation. */
+    WEEKEND_PACKAGE {
+        @Override
+        void checkEligibility(NewReservation request) {
+            boolean friday = request.checkIn().getDayOfWeek() == DayOfWeek.FRIDAY;
+            if (!friday || PriceCalculator.nights(request.checkIn(), request.checkOut()) != 2) {
+                throw new HotelException(
+                        ErrorCode.INVALID_REQUEST, "the weekend package is two nights, from a Friday to the Sunday after");
+            }
+        }
+
+        @Override
+        BigDecimal subtotal(NewReservation request, Room room) {
+            return WEEKEND_PRICES.get(room.type());
+        }
+
+        @Override
+        BigDecimal discount(NewReservation request, BigDecimal subtotal) {
+            return PriceCalculator.cents(BigDecimal.ZERO);
+        }
+
+        @Override
+        BigDecimal refund(BigDecimal amountPaid) {
+            return PriceCalculator.percentOf(amountPaid, new BigDecimal("0.50"));
+        }
+    },
+
+    /** 10% off for stays of seven nights or more. Everything comes back on cancellation. */
+    LONG_STAY {
+        @Override
+        void checkEligibility(NewReservation request) {
+            if (PriceCalculator.nights(request.checkIn(), request.checkOut()) < 7) {
+                throw new HotelException(ErrorCode.INVALID_REQUEST, "the long stay needs at least seven nights");
+            }
+        }
+
+        @Override
+        BigDecimal discount(NewReservation request, BigDecimal subtotal) {
+            return PriceCalculator.percentOf(subtotal, new BigDecimal("0.10"));
+        }
+    };
+
+    private static final Map<String, BigDecimal> COMPANY_DISCOUNTS = Map.of(
+            "TECNOSUL", new BigDecimal("0.12"),
+            "AGROVALE", new BigDecimal("0.18"),
+            "FARMAVIDA", new BigDecimal("0.25"));
+
+    private static final Map<RoomType, BigDecimal> WEEKEND_PRICES = Map.of(
+            RoomType.STANDARD, new BigDecimal("520.00"),
+            RoomType.DELUXE, new BigDecimal("820.00"),
+            RoomType.SUITE, new BigDecimal("1200.00"));
+
+    void checkEligibility(NewReservation request) {
+    }
+
+    BigDecimal subtotal(NewReservation request, Room room) {
+        return PriceCalculator.nightsTotal(room, request.checkIn(), request.checkOut());
+    }
+
+    BigDecimal discount(NewReservation request, BigDecimal subtotal) {
+        return PriceCalculator.cents(BigDecimal.ZERO);
+    }
+
+    BigDecimal refund(BigDecimal amountPaid) {
+        return amountPaid;
+    }
 }
